// Contact sheet generator for the 34 final SVGs. Uses sharp to rasterize each
// SVG (proving <use href="#frag">, clipPath, gradients all resolve) and lay
// them on a labeled grid grouped by asset family. No project files touched.
import sharp from 'sharp';
import fs from 'node:fs';
import path from 'node:path';

const ROOT = '/home/kfk/my/Dev/FF/Happy Dog Runner/.worktrees/196a2ab5-edb4-43a4-aa8e-a1c863c633ac';

// (label, w, h, relpath) — same set as the manifest, grouped for readability.
const groups = [
  ['dog', [
    ['dog_run', 140, 150], ['dog_jump', 140, 150], ['dog_hit', 140, 150],
    ['dog_victory', 160, 170], ['dog_defeat', 160, 170], ['dog_armored', 150, 160],
  ]],
  ['env', [
    ['park_bg_far', 1280, 720], ['park_bg_near', 1280, 360],
    ['ground_tile', 256, 160], ['park_fg_grass', 1280, 140],
  ]],
  ['entities', [
    ['tick', 64, 64], ['tablet', 56, 56], ['bush', 150, 110],
    ['puddle', 180, 50], ['armor_pickup', 64, 64], ['finish_line', 96, 480],
  ]],
  ['vfx', [
    ['vfx_armor_burst', 140, 140], ['vfx_armor_aura', 170, 170],
  ]],
  ['ui', [
    ['ui_heart_full', 52, 52], ['ui_heart_empty', 52, 52], ['ui_score_icon', 44, 44],
    ['ui_btn_pause', 64, 64], ['ui_btn_mute_on', 64, 64], ['ui_btn_mute_off', 64, 64],
    ['ui_progress_bar', 1180, 14], ['ui_title_logo', 720, 260], ['ui_btn_play', 360, 104],
    ['ui_promo_chip', 460, 120], ['ui_btn_cta', 380, 100], ['ui_btn_play_again', 300, 84],
    ['ui_pause_panel', 520, 360],
  ]],
  ['screens', [
    ['screen_bg_menu', 1280, 720], ['screen_bg_victory', 1280, 720], ['screen_bg_gameover', 1280, 720],
  ]],
];

const folderFor = { dog: 'dog', env: 'env', entities: 'entities', vfx: 'vfx', ui: 'ui', screens: 'screens' };

// Flatten with group label.
const items = [];
for (const [g, arr] of groups) for (const [k, w, h] of arr) items.push({ g, k, w, h });

const CELL_W = 280, CELL_H = 200, PAD = 12;
const COLS = 5;
const ROWS = Math.ceil(items.length / COLS);
const W = COLS * CELL_W;
const H = ROWS * CELL_H;

const bg = sharp({ create: { width: W, height: H, channels: 4, background: { r: 34, g: 38, b: 46, alpha: 1 } } }).png();
const composites = [];
const report = [];
let idx = 0;
for (const it of items) {
  const rel = `public/assets/${folderFor[it.g]}/${it.k}.svg`;
  const fp = path.join(ROOT, rel);
  const buf = fs.readFileSync(fp);
  // rasterize at logical size, then thumbnail to fit cell minus padding/label
  try {
    let img = sharp(buf, { density: 96 });
    const meta = await img.metadata();
    const maxW = CELL_W - PAD * 2 - 4;
    const maxH = CELL_H - PAD * 2 - 22;
    const scale = Math.min(maxW / it.w, maxH / it.h, 1);
    const tw = Math.max(1, Math.round(it.w * scale));
    const th = Math.max(1, Math.round(it.h * scale));
    const png = await img.resize(tw, th, { fit: 'contain', background: { r: 0, g: 0, b: 0, alpha: 0 } }).png().toBuffer();
    const col = idx % COLS, row = Math.floor(idx / COLS);
    const x = col * CELL_W + Math.round((CELL_W - tw) / 2);
    const y = row * CELL_H + PAD + 18 + Math.round((CELL_H - PAD - 18 - th) / 2);
    composites.push({ input: png, left: x, top: y });
    report.push(`OK  ${rel}  (${meta.width}x${meta.height} src -> ${tw}x${th})  use/clip/grad resolved`);
  } catch (e) {
    report.push(`ERR ${rel}  ${e.message}`);
  }
  idx++;
}

// Build a text-label SVG overlay (one label per cell).
const labelSvg = `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}">
<text x="0" y="0" font-family="monospace" font-size="11" fill="#cfd6df">
${items.map((it, i) => {
  const col = i % COLS, row = Math.floor(i / COLS);
  const x = col * CELL_W + PAD;
  const y = row * CELL_H + PAD + 12;
  return `<text x="${x}" y="${y}">${it.g}/${it.k}</text>`;
}).join('\n')}
</svg>`;
// Fix: the above nested text won't render (text inside text). Rebuild flat.
const labels = items.map((it, i) => {
  const col = i % COLS, row = Math.floor(i / COLS);
  const x = col * CELL_W + PAD;
  const y = row * CELL_H + PAD + 12;
  return `<text x="${x}" y="${y}" font-family="monospace" font-size="11" fill="#cfd6df">${it.g}/${it.k}</text>`;
}).join('');
const labelSvgFixed = `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}"><g font-family="monospace" font-size="11" fill="#cfd6df">${labels}</g></svg>`;
const labelBuf = Buffer.from(labelSvgFixed);

await sharp(await bg.then(b => b))
  .composite([...composites, { input: labelBuf, top: 0, left: 0 }])
  .png()
  .toFile('/tmp/svg_contact_sheet.png');

console.log(report.join('\n'));
console.log(`\nContact sheet: /tmp/svg_contact_sheet.png  (${W}x${H}, ${items.length} assets)`);

